function initRoadTripFlipCards(){document.querySelectorAll(".roadtrip-flip-btn").forEach(r=>{r.addEventListener("click",t=>{t.stopPropagation();r.closest(".roadtrip-card-flip").classList.toggle("flipped")})}),document.querySelectorAll(".roadtrip-card-back").forEach(r=>{r.addEventListener("click",()=>{r.closest(".roadtrip-card-flip").classList.remove("flipped")})})}